using Maintenance.Core;
using System.Text.Json;
namespace Maintenance.App;
sealed record SpeedHistoryEntry(string Run,string Mode,string Target,string Workload,string Direction,int Pass,long Bytes,double? Rate,string Unit,double? Iops,double? Latency,double? P95,double? P99,string Outcome,string Detail,DateTimeOffset RecordedAt=default,string Kind="Speed benchmark",string Summary="Speed benchmark");
sealed partial class MainWindow
{
    readonly DataGridView speedHistoryGrid=HistoryGrid();
    List<SpeedHistoryEntry> savedSpeeds=[];
    string speedRunId="",speedRunMode="",speedRunTarget="",speedSaveError="";
    void SaveSpeed(SpeedHistoryEntry entry){try{using var journal=store.StartJournal();LocalStore.Append(journal,entry with{Summary=$"Speed benchmark · {entry.Mode} · {entry.Workload} · {entry.Direction} · {entry.Outcome}"});}catch(Exception e)when(e is IOException or UnauthorizedAccessException){speedSaveError="History could not be saved: "+e.Message;}}
    void SaveSpeedSample(string workload,string direction,int pass,long bytes,double rate,string unit,double? iops=null,double? latency=null,double? p95=null,double? p99=null,string detail="")=>SaveSpeed(new(speedRunId,speedRunMode,speedRunTarget,workload,direction,pass,bytes,rate,unit,iops,latency,p95,p99,"Completed",detail));
    void SaveSpeedRun(string outcome,string detail)=>SaveSpeed(new(speedRunId,speedRunMode,speedRunTarget,"Run summary","—",0,0,null,"",null,null,null,null,outcome,detail));
    void ReadSpeedHistory(){var rows=new List<SpeedHistoryEntry>();foreach(var file in store.History())try{foreach(var line in File.ReadLines(file))try{using var json=JsonDocument.Parse(line);if(json.RootElement.TryGetProperty("Kind",out var kind)&&kind.GetString()=="Speed benchmark"){var entry=JsonSerializer.Deserialize<SpeedHistoryEntry>(line);if(entry!=null)rows.Add(entry);}}catch(JsonException){}}catch(IOException){}catch(UnauthorizedAccessException){}savedSpeeds=rows.GroupBy(r=>(r.Run,r.Workload,r.Direction,r.Pass)).Select(g=>g.OrderByDescending(r=>r.RecordedAt).First()).Select(r=>r.Outcome=="Started"?r with{Outcome=r.Run==speedRunId&&speedCancel!=null?"Running":"Interrupted / unknown",Detail="Completed individual results remain below; final status is pending."}:r).OrderByDescending(r=>r.RecordedAt).ToList();}
    void BuildSpeedHistoryTab(){var tab=new Panel{Text="Speed tests",Dock=DockStyle.Fill};tab.Controls.Add(speedHistoryGrid);historyTabs.TabPages.Add(tab);historyTabs.Controls.Add(tab);foreach(string name in new[]{"When","Test","Target","Workload","Direction","Pass","Result","Unit","Size (bytes)","Outcome","IOPS","Average µs","P95 µs","P99 µs","Details"})speedHistoryGrid.Columns.Add(new DataGridViewTextBoxColumn{Name=name,HeaderText=name,Width=name is "Target" or "Details"?360:160,SortMode=DataGridViewColumnSortMode.Automatic});speedHistoryGrid.CellFormatting+=(_,e)=>{if(e.Value is DateTimeOffset at){e.Value=at.LocalDateTime.ToString("g");e.FormattingApplied=true;}else if(e.Value is double value){e.Value=value.ToString("N2");e.FormattingApplied=true;}};speedHistoryGrid.SelectionChanged+=(_,_)=>{if(speedHistoryGrid.SelectedRows.Count>0&&speedHistoryGrid.SelectedRows[0].Tag is SpeedHistoryEntry r)historyExact.Text=$"{r.Target}\r\n{r.Mode} · {r.Workload} · {r.Outcome}\r\n{r.Detail}";};}
    void RenderSpeedHistory(string search){speedHistoryGrid.Rows.Clear();foreach(var r in savedSpeeds.Where(r=>$"{r.Mode} {r.Target} {r.Workload} {r.Direction} {r.Outcome} {r.Detail}".Contains(search,StringComparison.OrdinalIgnoreCase))){int i=speedHistoryGrid.Rows.Add(r.RecordedAt,r.Mode,r.Target,r.Workload,r.Direction,r.Pass==0?null:r.Pass,r.Rate,r.Unit,r.Bytes==0?null:r.Bytes,r.Outcome,r.Iops,r.Latency,r.P95,r.P99,r.Detail);speedHistoryGrid.Rows[i].Tag=r;}}
}

